    debug_assert!(
        result.iter().map(|r| r.exchanges).sum::<i64>() == exchanges.len() as i64,
        "sum_by: every exchange counted once"
    );
    debug_assert!(
        result.windows(2).all(|w| w[0].key < w[1].key),
        "sum_by: sorted by key"
    );
